UPDATE projectImages 
SET altText = 'Red Bull Jukebox CNC fabrication drawings by Brandon PT Davis - Technical elevation and section drawings for monumental LED wall arch with precise panel segmentation and connection details.'
WHERE projectId = 90007 AND imageUrl LIKE '%rbj-cnc-page-1%';

UPDATE projectImages 
SET altText = 'Red Bull Jukebox CNC layout drawings by Brandon PT Davis - Detailed CNC cutting patterns for layered façade components with arc radii coordination and assembly sequencing.'
WHERE projectId = 90007 AND imageUrl LIKE '%rbj-cnc-page-2%';

UPDATE projectImages 
SET altText = 'Red Bull Jukebox fabrication documentation by Brandon PT Davis - CNC panel layouts with dimensional specifications, material callouts (aluminum/MDF), and truss system integration details.'
