UPDATE projectImages 
SET altText = 'Red Bull Jukebox technical drawings by Brandon PT Davis - Human-scale reference drawings showing LED arch proportions, sightline analysis, and venue integration for Ascend Amphitheater.'
WHERE projectId = 90007 AND imageUrl LIKE '%rbj-cnc-page-4%';

